from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    stack = []
    current = ""

    for char in paren_string:
        if char == '(':
            if stack:
                current += char
            stack.append(char)
        elif char == ')':
            stack.pop()
            current += char
            if not stack:
                result.append(current)
                current = ""

    return result

